/* kit.js — the design system as shipped: tokens read back from tokens.css, and every
   component rendered with the same functions and classes the routes use, in each of its states. */
(function () {
  "use strict";
  const { $, $$, esc, I, Tally, StackBar, PipRow, Hint, Keycaps, Wave, Src, State, LedgerLink } = GT;
  const M = window.GT_MODEL, ST = window.GT_STUDIO;
  $("#hdr").innerHTML = GT.header({ current: "kit" });
  const cssv = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  const plates = M.media.filter((m) => m.kind === "forge.candidate");
  const take = M.keptTakes.find((t) => t.kind === "music") || M.takes[0];
  const slotBy = (st) => M.slots.find((s) => s.status === st);
  const spec = (name, cls, body, extra) => `<div class="spec ${extra || ""}"><div class="nm"><b>${esc(name)}</b><span>${esc(cls)}</span></div>${body}</div>`;
  const sec = (id, title, sub, body, min) => `<section class="k-sec" id="${id}"><h2>${esc(title)}<span class="mono">${esc(sub)}</span></h2><div class="k-grid" style="--min:${min || 260}px">${body}</div></section>`;
  const SECTIONS = [];
  const add = (grp, id, title, sub, body, min) => SECTIONS.push({ grp, id, title, html: sec(id, title, sub, body, min) });

  /* ───────── tokens ───────── */
  const sw = (v, meaning) => `<div class="sw"><i style="background:var(${v})"></i><span>${v}</span><small>${esc(cssv(v))}${meaning ? " · " + esc(meaning) : ""}</small></div>`;
  add("Tokens", "colour", "Colour", "tokens.css · :root", [
    spec("ground", "--ink…--ink-4", `<div class="k-grid" style="--min:90px">${["--ink", "--ink-1", "--ink-2", "--ink-3", "--ink-4"].map((v) => sw(v)).join("")}</div>`, "k-wide"),
    spec("text", "--ink-bright · --text · --muted · --faint", `<div class="k-grid" style="--min:120px">${[["--ink-bright", "titles"], ["--text", "body"], ["--muted", "meta"], ["--faint", "labels ≥12px"]].map(([v, m]) => sw(v, m)).join("")}</div>`),
    spec("signal · one meaning each", "--cyan --amber --emerald --rose --violet", `<div class="k-grid" style="--min:120px">${[["--cyan", "running · focus"], ["--amber", "awaiting you · weir"], ["--emerald", "ratified · library"], ["--rose", "failed · rejected"], ["--violet", "calendar · agent"]].map(([v, m]) => sw(v, m)).join("")}</div>`, "k-wide"),
    spec("actors · ledger", "--actor-*", `<div class="k-grid" style="--min:110px">${[["--actor-operator", "operator"], ["--actor-agent", "agent"], ["--actor-machine", "machine"]].map(([v, m]) => sw(v, m)).join("")}</div>`),
    spec("the wall", "--wall · --wall-hi", `<div class="k-grid" style="--min:110px">${sw("--wall", "weir")}${sw("--wall-hi", "sluice")}</div>`),
    spec("hairlines", "--hair · --hair-2 · --hair-3", `<div class="col">${["--hair", "--hair-2", "--hair-3"].map((v) => `<div class="row"><span class="lab">${v}</span><i style="flex:1;height:0;border-top:1px solid var(${v})"></i></div>`).join("")}</div>`),
  ].join(""));
  const TYPE = [["--fs-micro", "12px · mono caps", `<span class="chip">chip · tally · label</span> <span class="state running">running</span>`], ["--fs-meta", "13px · mono meta", `<span class="mono" style="font-size:13px;color:var(--muted)">2026-08-26-sweep-01 · 20 plates</span>`],
    ["--fs-ui", "14px · rows, controls", `<span style="font-size:14px;color:var(--ink-bright)">Glass Harbor — trailer · cut</span>`], ["--fs-body", "15px · body", `<span style="font-size:15px">A crew that never breaks in waits for the one door every city leaves unlocked.</span>`],
    ["--fs-read", "17px · serif reading", `<span style="font:17px/1.6 var(--serif);color:#e9e4d8">${esc((M.styles[0] || {}).recipe || "").slice(0, 120)}…</span>`], ["--fs-h2", "19px · desk title", `<span style="font:600 19px/1.2 var(--sans);color:var(--ink-bright)">Forge · 2026-08-26-sweep-01</span>`],
    ["project title", "24px · serif", `<span class="ptitle" style="white-space:normal">Why the Bitcoin price does not rise</span>`], ["--fs-h1", "32px · serif detail", `<span style="font:600 32px/1.15 var(--serif);color:var(--ink-bright)">Painted 3D</span>`]];
  add("Tokens", "type", "Type", "Inter · JetBrains Mono · Iowan Old Style — nothing readable under 12px", spec("scale", "--fs-*", TYPE.map(([t, m, ex]) => `<div class="type-row"><span class="mono">${esc(t)}<br>${esc(m)}</span><span>${ex}</span></div>`).join(""), "k-wide"), 600);
  add("Tokens", "space", "Space · radii", "--sp-1…7 · --r-xs…--r-lg",
    spec("space", "--sp-*", `<div class="col">${[1, 2, 3, 4, 5, 6, 7].map((n) => `<div class="space-row"><span class="lab">--sp-${n} · ${esc(cssv("--sp-" + n))}</span><i style="width:var(--sp-${n})"></i></div>`).join("")}</div>`) +
    spec("radii", "--r-*", `<div class="row">${["--r-xs", "--r-sm", "--r", "--r-lg"].map((v) => `<div class="col" style="align-items:center"><div class="radius-box" style="border-radius:var(${v})"></div><span class="lab" style="min-width:0">${v} · ${esc(cssv(v))}</span></div>`).join("")}</div>`) +
    spec("frame", "--hdr-h · --head-h · --cal-w", `<div class="col">${["--hdr-h", "--head-h", "--cal-w"].map((v) => `<div class="row"><span class="lab">${v}</span><span class="mono" style="color:var(--ink-bright);font-size:13px">${esc(cssv(v))}</span></div>`).join("")}</div>`));
  add("Tokens", "motion", "Motion", "--ease " + cssv("--ease") + " · meaning, not decoration",
    spec("acts", "click to replay", `<div class="motion-demo">${[["play-lock", "lockIn · ratified"], ["play-fade", "fadeUp · arrive"], ["play-moved", "moved · re-routed"], ["play-shake", "shake · refused"]].map(([c, l]) => `<button data-play="${c}">${esc(l)}</button>`).join("")}</div>`, "k-wide") +
    spec("durations", "--dur-*", `<div class="col">${["--dur-fast", "--dur", "--dur-slow"].map((v) => `<div class="row"><span class="lab">${v}</span><span class="mono" style="color:var(--ink-bright)">${esc(cssv(v))}</span></div>`).join("")}<div class="row"><span class="lab">reduced</span><span class="mono">prefers-reduced-motion → none</span></div></div>`));

  /* ───────── signal vocabulary ───────── */
  add("Signal", "chip", "Chip · Tally · Src", "the vocabulary that replaced prose",
    spec("Chip", ".chip", `<div class="row"><span class="chip">default</span><span class="chip cyan">cyan</span><span class="chip amber">amber</span><span class="chip emerald">emerald</span><span class="chip rose">rose</span><span class="chip violet">violet</span><span class="chip ghost">ghost · fixture</span><span class="chip emerald"><span class="dot"></span>weir clear</span><span class="chip lc">lower case</span><button class="chip">button ›</button></div>`) +
    spec("Tally", "GT.Tally(v, label, of)", `<div class="row">${Tally(20)}${Tally(14, "waiting")}${Tally(3, "agreement", 4)}${Tally("48.2k", "views")}</div>`) +
    spec("Src · provenance", "GT.Src(kind)", `<div class="row">${Src("real")}${Src("fixture")}${Src("illustrative")}${Src("session")}${Src("model")}</div>`) +
    spec("LedgerLink", "GT.LedgerLink(id)", `<div class="row">${LedgerLink("pkt_audio", "ledger")}${LedgerLink("painted-3d", "ledger")}</div>`));
  add("Signal", "state", "State · PipRow · StackBar", "status vocabulary — one dot, one colour",
    spec("State", "GT.State(s)", `<div class="col">${["draft", "queued", "running", "awaiting_gate", "ratified", "failed", "blocked", "paused"].map((s) => State(s)).join("")}</div>`) +
    spec("PipRow", "GT.PipRow(states)", `<div class="col"><div class="row"><span class="lab">shipped</span>${PipRow(["ratified", "ratified", "ratified", "ratified", "ratified", "ratified"], "")}</div><div class="row"><span class="lab">at weir</span>${PipRow(["ratified", "ratified", "awaiting_gate", "draft", "draft", "draft"], "")}</div><div class="row"><span class="lab">running</span>${PipRow(["ratified", "running", "draft", "draft", "draft", "draft"], "")}</div><div class="row"><span class="lab">blocked</span>${PipRow(["ratified", "ratified", "blocked", "draft", "draft", "draft"], "")}</div></div>`) +
    spec("StackBar", "GT.StackBar(k, x, u)", `<div class="col"><div class="row"><span class="lab">undecided</span><div style="flex:1">${StackBar(0, 0, 20)}</div></div><div class="row"><span class="lab">mid-cull</span><div style="flex:1">${StackBar(6, 5, 9)}</div></div><div class="row"><span class="lab">committed</span><div style="flex:1">${StackBar(8, 12, 0)}</div></div></div>`));
  add("Signal", "keys", "Keycaps · Hint · Ghost", "keys are a table, not prose · a disclosure holds ~12 words",
    spec("Keycaps", "GT.Keycaps(map)", Keycaps([[["K"], "keep"], [["X"], "reject"], [["U"], "undecide"], [["1", "2", "3", "4"], "reason"], [["Z"], "zoom"], [["⌫"], "undo"], [["⏎"], "commit"]])) +
    spec("Hint", "GT.Hint(text)", `<div class="row"><span class="chip">spend 24h <b>$0.00</b></span>${Hint("local GPU runs $0 · article range is the pipeline hint")}</div>`) +
    spec("Ghost", ".ghost-card", `<div class="col"><div class="ghost-card" style="height:34px"></div><div class="ghost-card" style="height:34px"></div></div>`));

  /* ───────── controls ───────── */
  add("Controls", "buttons", "Buttons", "hover · focus · active · disabled",
    spec("Btn", ".btn .btn.{emerald|amber|rose|violet|cyan} .sm", `<div class="row"><button class="btn">Default</button><button class="btn emerald">Approve → slot <kbd class="keycap">A</kbd></button><button class="btn amber">Edit plan · 2</button><button class="btn rose">Reject <kbd class="keycap">R</kbd></button><button class="btn violet">Slot</button><button class="btn cyan">Open in Runs</button><button class="btn sm">sm</button></div>
      <div class="row"><span class="lab">hover</span><button class="btn hover-demo">Hover</button><span class="lab">focus</span><button class="btn focus-demo">Focus</button><span class="lab">disabled</span><button class="btn" disabled>Disabled</button></div>`, "k-wide") +
    spec("Launch", ".launch · composer", `<button class="launch" style="width:220px">Launch <kbd class="keycap">⏎</kbd></button><div data-component="Estimate"><span><b>20</b> plates</span><span>~<b>32</b> min</span><span><b>$0</b> local</span><span>queue <b>#1</b></span><span class="ill">illus.</span></div>`) +
    spec("Commit", ".commit · .wait · .refuse", `<div class="col"><button class="commit" style="margin:0">Commit packet <kbd class="keycap">⏎</kbd></button><button class="commit wait" style="margin:0">Commit packet <span class="chip">7 undecided</span><kbd class="keycap">⏎</kbd></button><button class="commit refuse" style="margin:0">Commit packet <span class="chip">7 undecided</span></button></div>`) +
    spec("Launch plan", ".launch-plan", `<button class="launch-plan" style="margin:0">Launch plan <span class="mono">$1.60 · 3h 10m</span><kbd class="keycap">⏎</kbd></button>`) +
    spec("Toggle · Seg", ".toggle · .seg", `<div class="row"><button class="toggle" aria-pressed="true">music</button><button class="toggle" aria-pressed="false">sfx</button><button class="toggle" aria-pressed="true">text+ref</button></div><div class="seg"><button aria-pressed="false">12h</button><button aria-pressed="true">24h</button><button aria-pressed="false">3d</button><button aria-pressed="false">week</button></div>`) +
    spec("Field · Search · Select", ".field · .search", `<div class="col"><div class="search">${I.search}<input class="field" placeholder="mood:tense · kind:audio"><kbd class="keycap">/</kbd></div><input class="field" value="Untitled film"><select class="field"><option>Flux 2 dev fp8 · GPU box — 1h 04m · $0</option><option>Nano Banana · Google — 14m · $1.60</option></select></div>`));

  /* ───────── floor ───────── */
  const pile = (its, n) => `<button data-component="Pile" style="width:150px"><div class="pile-face"><span class="mode mode-glyph">${I.cull}</span>${its.map((m, i) => `<div class="sheet-l ${i === 0 ? "l2" : i === 1 ? "l1" : ""}"><img src="${m.url}" alt=""></div>`).join("")}${Tally(n)}</div><span class="pile-title">Forge · 2026-08-26-sweep-01</span>${StackBar(6, 4, 10)}<span class="pile-sub">matrix cull</span></button>`;
  const runRow = (st, title, meta, prog, img) => `<div data-component="RunRow" data-status="${st}" style="animation:none"><div class="run-thumb">${img ? `<img src="${img}" alt="">` : '<span class="para">¶</span>'}</div><div style="min-width:0"><div class="run-title">${esc(title)}</div><div class="run-meta">${State(st)}${meta}</div><div class="run-bar ${st === "running" && prog == null ? "shimmer" : ""}"><i style="width:${Math.round((prog || 0) * 100)}%"></i></div></div></div>`;
  const tile = (m, cls, badge, reason) => `<button data-component="CullTile" class="${cls}" style="width:190px"><img src="${m.url}" alt=""><span class="cap"><span class="ell">${esc((M.styleById[m.style] || {}).name || m.style || "plate")}</span><span class="m">${esc(m.mechanism || "")}</span></span><span class="badge">${badge}</span>${reason ? `<span class="reason chip rose on">${reason}</span>` : ""}</button>`;
  const slotRow = (s) => s ? `<button data-component="SlotRow" class="${s.status}"><span class="tm">${s.publishAt.slice(11, 16)}</span><span class="chan ${s.channelId}">${{ youtube: "YT", tiktok: "TT", instagram: "IG", blog: "PR" }[s.channelId]}</span><span style="min-width:0"><span class="ttl" style="display:block;color:var(--ink-bright)">${esc(s.title)}</span><span class="st state ${s.status === "scheduled" ? "awaiting_gate" : s.status === "publishing" ? "running" : s.status === "published" ? "ratified" : s.status === "failed" || s.status === "missed" ? "blocked" : "draft"}" style="display:inline-flex">${s.status}</span>${s.error && s.status !== "cancelled" ? `<span class="err">${I.warn}<span>${esc(s.error)}</span></span>` : ""}</span></button>` : "";
  add("Floor", "floor", "Floor · Foundry → Weir → Library", "floor.css",
    spec("RunRow", "[data-component=RunRow] · draft · running · awaiting_gate", `<div class="col">${runRow("draft", "Forge · Teal-Orange Blockbuster", '<span>queue #2</span>', 0, plates[3] && plates[3].url)}${runRow("running", "Forge · Cold Photoreal CG", '<span>9/20</span><span>plates</span>', 0.45, plates[1] && plates[1].url)}${runRow("running", "judge calibration and drift", '<span class="stagepips"><i class="done"></i><i class="done"></i><i class="done"></i><i class="cur"></i><i></i></span><span>critique</span>', null)}${runRow("awaiting_gate", "2026-08-26-sweep-01", "<span>20 items</span>", 1, plates[0] && plates[0].url)}</div>`) +
    spec("Pile", "[data-component=Pile] · .next", `<div class="row" style="padding:6px">${pile(plates.slice(0, 3), 20)}</div>`) +
    spec("CullTile", "[data-component=CullTile] · cur · keep · reject+reason", `<div class="row">${tile(plates[4], "cur", "✓")}${tile(plates[5], "keep", "✓")}${tile(plates[6], "reject", "✕", "style")}</div>`, "k-wide") +
    spec("SlotRow", "[data-component=SlotRow] · each status", `<div class="col">${["scheduled", "publishing", "published", "failed", "cancelled"].map((st) => slotRow(slotBy(st))).join("")}</div>`) +
    spec("UpstreamBreak", "[data-component=UpstreamBreak]", `<div data-component="UpstreamBreak"><div class="ub-rail"><span class="ub-node"><i></i>scheduled</span><span class="ub-link"></span><span class="ub-node brk"><i></i>auth</span><span class="ub-link off"></span><span class="ub-node todo"><i></i>upload</span><span class="ub-link off"></span><span class="ub-node todo"><i></i>live</span></div><div class="ub-err">${esc((M.slots.find((s) => /OAuth/.test(s.error || "")) || {}).error || "")}</div></div>`) +
    spec("Crumbs", "[data-component=Crumbs]", `<nav data-component="Crumbs"><button>Floor</button><span class="sep">›</span><button>Board</button><span class="sep">›</span><button>Image</button><span class="sep">›</span><span class="here">Forge · 2026-08-26-sweep-01</span></nav>`));
  // calendar month day (the same markup the month renders)
  const mslot = (s) => s ? `<button class="mslot ${s.status === "scheduled" ? "awaiting_gate" : s.status === "published" ? "ratified" : s.status === "failed" || s.status === "missed" ? "blocked" : s.status === "publishing" ? "running" : "draft"} ${s.status}"><span class="mrow"><span class="tm">${s.publishAt.slice(11, 16)}</span><span class="chan ${s.channelId}">${{ youtube: "YT", tiktok: "TT", instagram: "IG" }[s.channelId]}</span><span class="ell t">${esc(s.title)}</span></span>${(s.status === "failed" || s.status === "missed") && s.error ? `<span class="merr">${esc(s.error)}</span>` : ""}</button>` : "";
  add("Floor", "calendar", "Calendar · rail ⇄ month", "keys · C ⇄ Esc",
    spec("Month day", ".mday · today · has-fail · sel", `<div class="row" style="align-items:stretch">${[["today", ["publishing", "scheduled"], true], ["has-fail", ["failed", "published"], false], ["sel", ["scheduled", "cancelled"], false]].map(([c, sts, now]) => `<div class="mday ${c}" style="width:220px;height:150px"><div class="mday-h"><span class="dn">${c === "today" ? 14 : c === "sel" ? 20 : 12}</span>${c === "today" ? '<span class="chip cyan" style="height:20px">today</span>' : ""}${c === "has-fail" ? `<span class="mfail">${I.warn.replace("<svg", '<svg width="11" height="11"')}1</span>` : ""}<span class="mcount">${sts.length}</span></div><div class="mlist">${now ? '<span class="mnow"><b>NOW 09:12</b></span>' : ""}${sts.map((st) => mslot(slotBy(st))).join("")}</div></div>`).join("")}</div>`, "k-wide"));

  /* ───────── composition ───────── */
  const laneChips = [...ST.LANES.map((l) => l.id), "gate", "calendar"].map((id) => `<span class="lane-chip l-${id.replace(".", "-")}">${esc(ST.laneById[id] ? ST.laneById[id].label : id === "gate" ? "Weir · operator" : "Calendar")}</span>`).join("");
  const bars = [["s-running", "frames ×40", 10, 150, 0, '<i class="prog" style="width:45%"></i>'], ["s-queued", "motion ×14", 170, 160, 0], ["s-done", "script", 10, 90, 1], ["gatebar s-gate", "◆ frames", 110, 60, 1], ["s-failed", "frames ×18", 180, 110, 1], ["s-paused", "score ×2", 300, 100, 1], ["s-queued blocked", "cut", 10, 120, 2], ["s-queued aftergate", "motion ×6", 140, 120, 2], ["s-planned ghost", "still ×2", 270, 90, 2], ["slotbar", "slot", 370, 50, 2], ["s-queued sel", "words", 340, 70, 0]];
  add("Composition", "runs", "Composition · Plan · Runs", "projects.css · one row per resource",
    spec("Resource chips", ".lane-chip.l-*", `<div class="row">${laneChips}</div>`, "k-wide") +
    spec("Job bar · every state", ".bar.s-{running|queued|done|gate|failed|paused} .blocked .aftergate .ghost .slotbar .sel", `<div class="track-demo">${bars.map(([c, l, x, w, row, inner]) => `<button class="bar ${c}" style="left:${x}px;width:${w}px;top:${8 + row * 44}px;height:30px">${inner || ""}<span class="bl">${esc(l)}</span></button>`).join("")}</div><div class="row"><span class="lab">dep links</span><svg width="260" height="40"><path class="lk" d="M10,20 C60,20 60,8 110,8"/><path class="lk up" d="M120,20 C160,20 160,32 200,32"/><path class="lk down" d="M200,10 C230,10 230,30 250,30"/><path class="lk bad" d="M10,34 C60,34 80,38 110,38"/></svg><span class="mono" style="font-size:12px;color:var(--faint)">plain · upstream · downstream · blocked</span></div>`, "k-wide") +
    spec("Idea → Slot ribbon", ".ribbon .rnode", `<div class="ribbon"><span class="rnode idea ratified"><i></i><span>idea</span></span><span class="rlink"></span><span class="rnode ratified"><i></i><span>script</span></span><span class="rlink"></span><span class="rnode running"><i></i><span>frames</span></span><span class="rlink"></span><span class="rnode gate awaiting_gate"><i></i><span>◆ frames</span></span><span class="rlink"></span><span class="rnode failed"><i></i><span>motion</span></span><span class="rlink"></span><span class="rnode queued"><i></i><span>cut</span></span><span class="rlink"></span><span class="rnode slot awaiting_gate"><i></i><span>YT Thu 15 Oct 15:00</span></span></div>`, "k-wide") +
    spec("Re-route option", ".alt · Δ before the act", `<div class="alts"><div class="alt cur"><span class="lane-chip l-gpu-local">GPU box</span><span class="am">Flux 2 dev fp8 · ComfyUI</span><span class="chip" style="height:20px">current</span></div><button class="alt"><span class="lane-chip l-cloud-google">Google</span><span class="am">Nano Banana</span><span class="ad"><span class="mono">14m · $1.60</span><span class="d good">eta −1h 23m</span><span class="d bad">+$1.60</span><span class="mono">q#1</span></span></button></div>`) +
    spec("Resource summary", ".res · per resource", `<div class="res-list">${[["gpu.local", 98, "$0"], ["cloud.google", 14, "$1.60"], ["seat.text", 23, "$0"]].map(([l, m, u]) => `<div class="res"><div class="res-h"><span class="lane-chip l-${l.replace(".", "-")}">${esc(ST.laneById[l].label)}</span></div><div class="res-bar"><i style="width:${Math.round((m / 98) * 100)}%"></i></div><div class="res-n"><span class="mono">${ST.fmtDur(m)}</span><span class="mono">${u}</span></div></div>`).join("")}</div>`) +
    spec("Composition row", ".prow · on", `<div class="col">${["seed-glass-harbor-trailer", "seed-the-quiet-tariff"].map((id, i) => { const p = ST.projectById(id); const t = ST.projectTotals(id); return `<a class="prow ${i === 0 ? "on" : ""}" style="margin:0"><span class="pic">${I.video}</span><span class="pt"><span class="ell ttl">${esc(p.title)}</span><span class="meta">${PipRow(ST.jobsOf(id).filter((j) => j.part !== "gate" && j.part !== "slot").map((j) => j.status === "done" ? "ratified" : j.status === "failed" ? "blocked" : j.status === "running" ? "running" : "draft"), "")}</span></span><span class="pr">${t.failed ? `<span class="chip rose" style="height:20px">${t.failed}</span>` : `<span class="chip amber" style="height:20px">${t.gates}</span>`}<span class="mono usd">$0</span></span></a>`; }).join("")}</div>`));

  /* ───────── library + ledger: their components, live on their own routes ───────── */
  const frame = (src, label) => `<iframe class="k-frame" src="${src}" title="${esc(label)}" loading="lazy"></iframe>`;
  add("Routes", "library", "Library · vocabulary rail · virtual grid · detail", "library.css · live",
    spec("Library · audio facets", "library.html#kind=audio", frame("library.html#kind=audio", "library audio"), "k-wide") +
    spec("Library · style detail", "library.html#kind=style&sel=painted-3d", frame("library.html#kind=style&sel=painted-3d&view=list", "library style"), "k-wide"), 600);
  add("Routes", "ledger", "Ledger · time strip · facets · event · jsonl", "ledger.css · live",
    spec("Ledger · agent acts", "ledger.html#actor=agent", frame("ledger.html#actor=agent", "ledger agent"), "k-wide") +
    spec("Ledger · publish failures", "ledger.html#type=publish.fail", frame("ledger.html#type=publish.fail", "ledger failures"), "k-wide") +
    spec("Audio wave", "GT.Wave(peaks)", `<div class="row">${Wave(take.peaks, 220, 34, "#a78bfa")}${Wave(take.peaks, 220, 34, "#67e8f9", 0.4)}</div>`), 600);

  // nav
  let grp = ""; const nav = SECTIONS.map((s) => { const g = s.grp !== grp ? `<div class="grp">${esc(s.grp)}</div>` : ""; grp = s.grp; return g + `<a href="#${s.id}" data-sec="${s.id}">${esc(s.title)}</a>`; }).join("");
  $("#kitnav").innerHTML = nav;
  $("#kitbody").innerHTML = SECTIONS.map((s) => s.html).join("");
  document.addEventListener("click", (e) => {
    const b = e.target.closest("[data-play]"); if (!b) return;
    b.classList.remove(b.dataset.play); void b.offsetWidth; b.classList.add(b.dataset.play);
  });
  const io = new IntersectionObserver((es) => es.forEach((en) => { if (en.isIntersecting) $$(".kit-nav a").forEach((a) => a.classList.toggle("on", a.dataset.sec === en.target.id)); }), { root: $("#kitbody"), rootMargin: "0px 0px -70% 0px" });
  $$(".k-sec").forEach((s) => io.observe(s));
})();
